(lib.LevelSelect = function(mode,startPosition,loop,reversed) {
if (loop == null) { loop = true; }
if (reversed == null) { reversed = false; }
	var props = new Object();
	props.mode = mode;
	props.startPosition = startPosition;
	props.labels = {};
	props.loop = loop;
	props.reversed = reversed;
	cjs.MovieClip.apply(this,[props]);

	this.isSingleFrame = false;
	// timeline functions:
	this.frame_0 = function() {
		if(this.isSingleFrame) {
			return;
		}
		if(this.totalFrames == 1) {
			this.isSingleFrame = true;
		}
		this.stop();
		var ts = this;
		caller(6, onMouseClick);
		createjs.Tween.get(ts, {
			useTicks: true
		}).wait(1).call(initLevelBtns);
		var lbsts = [];
		var startLevel = 1;
		var lonpage = 20;
		var rowspage = 4;
		var STARTX = 404;
		var STARTY = 205;
		var INCX = 120;
		var INCY = 104;
		var currentLevel = caller(2, "level");
		
		function initLevelBtns() {
			lg.translate("lvlT", ts.ttl.txt, {upper:true});
			lg.translate("lvlT", ts.ttl.txt1, {upper:true});
			lg.scaleTextBox(ts.ttl);
			var sx = STARTX;
			var sy = STARTY;
			for (var i = startLevel; i < startLevel + lonpage; i++) {
				var lbtn = new lib.LevelS();
				lbtn.name = "lbtn";
				lbtn.txt.text = i + "";
				lbtn.txt1.text = i + "";
				lg.setGameFont(lbtn.txt);
				lg.setGameFont(lbtn.txt1);
				lbtn.x = sx;
				lbtn.y = sy;
				sx += INCX;
				lbtn.gotoAndStop(0);
				if (i > currentLevel) {
					lbtn.gotoAndStop(1);
					lbtn.mouseEnabled = false;
				}
				lbtn.mouseChildren = false;
				lbtn.cursor = "pointer";
				ts.addChild(lbtn);
				if (i % (lonpage / rowspage) == 0) {
					sx = STARTX;
					sy += INCY
				}
				lbsts.push(lbtn);
			}
			startLevel = (Math.floor((currentLevel - 1) / lonpage) * lonpage) + 1;
			if (startLevel > lg.totalLevels) {
				startLevel -= lonpage;
			}
			updateLevels();
		}
		function updateLevels() {
			var idx = 0;
			ts.lp.cp.x = 60 * Math.floor(startLevel / lonpage);
			for (var i = startLevel; i < startLevel + lonpage; i++) {
				var lbtn = lbsts[idx];
				lbtn.txt.text = i + "";
				lbtn.txt1.text = i + "";
				lbtn.gotoAndStop(0);
				lbtn.mouseEnabled = true;
				if (i > currentLevel) {
					lbtn.gotoAndStop(1);
					lbtn.mouseEnabled = false;
				}
				lbtn.mouseChildren = false;
				idx++;
			}
		}
		function onMouseClick(event) {
			if (event.target.name == "lbtn") {
				var lno = Number(event.target.txt.text);
				lg.playingLevel = lno;
				caller(7, onMouseClick);
				caller(4, ts);
				caller(3, new lib.GamePlay());
			}
			switch (event.target.name) {
				case "mainMenu":
					caller(7, onMouseClick);
					caller(4, ts);
					caller(3, new lib.IntroScreen());
					break;
				case "p1":
				case "p2":
				case "p3":
				case "p4":
					var n = Number(event.target.name.replace("p", ""));
					startLevel = (n * lonpage) - lonpage + 1;
					updateLevels();
					break;
				case "nextLevels":
					if (startLevel + (lonpage - 1) == lg.totalLevels) {
						return;
					} else {
						startLevel += lonpage;
						updateLevels();
					}
					break;
				case "prevLevels":
					if (startLevel == 1) {
						return;
					} else {
						startLevel -= lonpage;
						updateLevels();
					}
					break;
			}
		}
	}

	// actions tween:
	this.timeline.addTween(cjs.Tween.get(this).call(this.frame_0).wait(1));

	// Layer_1
	this.mainMenu = new lib.AG();
	this.mainMenu.name = "mainMenu";
	this.mainMenu.setTransform(1179.2,624.9,1,1,0,0,0,1.1,0.7);
	new cjs.ButtonHelper(this.mainMenu, 0, 1, 2, false, new lib.AG(), 3);

	this.lp = new lib.BW();
	this.lp.name = "lp";
	this.lp.setTransform(610,624.95);

	this.ttl = new lib.AE();
	this.ttl.name = "ttl";
	this.ttl.setTransform(640,118.85);

	this.instance = new lib.ET();
	this.instance.setTransform(242.75,25);

	this.instance_1 = new lib.GBG();
	this.instance_1.setTransform(640,360,1,1,0,0,0,640,360);

	this.timeline.addTween(cjs.Tween.get({}).to({state:[{t:this.instance_1},{t:this.instance},{t:this.ttl},{t:this.lp},{t:this.mainMenu}]}).wait(1));

	this._renderFirstFrame();

}).prototype = p = new cjs.MovieClip();
p.nominalBounds = new cjs.Rectangle(0,0,1280,720);


