	this.instance_1 = new lib.GBG();
	this.instance_1.setTransform(640,360,1,1,0,0,0,640,360);

	this.timeline.addTween(cjs.Tween.get({}).to({state:[{t:this.instance_1},{t:this.instance},{t:this.ttl},{t:this.txt},{t:this.nextBtn}]}).wait(1));

	this._renderFirstFrame();

