(lib.GameOver = function(mode,startPosition,loop,reversed) {
if (loop == null) { loop = true; }
if (reversed == null) { reversed = false; }
	var props = new Object();
	props.mode = mode;
	props.startPosition = startPosition;
	props.labels = {};
	props.loop = loop;
	props.reversed = reversed;
	cjs.MovieClip.apply(this,[props]);

	this.isSingleFrame = false;
	// timeline functions:
	this.frame_0 = function() {
		if(this.isSingleFrame) {
			return;
		}
		if(this.totalFrames == 1) {
			this.isSingleFrame = true;
		}
		this.stop();
		var ts = this;
		function updateScore() {
			let sbW  = 700;
			lg.translate("tScore", ts.scr.total_txt, {
				upper: true
			});
			ts.scr.total_score.text = lg.getTotalScore();
			lg.setGameFont(ts.scr.total_score);
		
			lg.translate("bScore", ts.scr.best_txt, {
				upper: true
			});
			ts.scr.best_score.text = caller(2, "bestScore");
			lg.setGameFont(ts.scr.best_score);
			var b = ts.scr.getTransformedBounds();
			if (sbW / b.width < 1) {
				ts.scr.scaleX = ts.scr.scaleY = sbW / b.width;
			}
			lg.translate("tfT", ts.ttl.txt, {
				upper: true
			});
			lg.translate("tfT", ts.ttl.txt1, {
				upper: true
			});
			lg.scaleTextBox(ts.ttl);
		}
		
		createjs.Tween.get(ts, {
			useTicks: true
		}).wait(1).call(updateScore);
		caller(6, onmbutton);
		
		function nextCall() {
			caller(4, ts);
			caller(3, new lib.GamePlay());
		}
		
		function nextCall2() {
			caller(4, ts);
			caller(3, new lib.IntroScreen());
		}
		function onmbutton(eobj) {
			switch (eobj.target.name) {
				case "retryBtn":
					caller(7, onmbutton);
					caller(42, nextCall);
					break;
				case "mainnenu":
					caller(7, onmbutton);
					caller(42, nextCall2);
					break;
		
			}
		}
	}

	// actions tween:
	this.timeline.addTween(cjs.Tween.get(this).call(this.frame_0).wait(1));

	// Layer_1
	this.scr = new lib.AX();
	this.scr.name = "scr";
	this.scr.setTransform(640,372.35);

	this.instance = new lib.AW();
	this.instance.setTransform(643,583.6);

	this.ttl = new lib.AE();
	this.ttl.name = "ttl";
	this.ttl.setTransform(640.05,120.05);

	this.instance_1 = new lib.ET();
	this.instance_1.setTransform(243,25);

	this.instance_2 = new lib.GBG();
	this.instance_2.setTransform(640,360,1,1,0,0,0,640,360);

	this.timeline.addTween(cjs.Tween.get({}).to({state:[{t:this.instance_2},{t:this.instance_1},{t:this.ttl},{t:this.instance},{t:this.scr}]}).wait(1));

	this._renderFirstFrame();

}).prototype = p = new cjs.MovieClip();
p.nominalBounds = new cjs.Rectangle(0,0,1280,720);


